vec2 Hash12( in float t )
{
    float x = fract( sin(t * 346.43 + 1.) * 573.436 );
    float y = fract( sin((t+x) * 235.53 + 1.) * 873.726 );

    return vec2(x, y) * 2. - 1.;
}

vec2 Hash12_Polar( in float t )
{
    float a = fract( sin(t * 246.43 + 1.) * 173.436 ) * 6.2832;
    float r = fract( sin((t+a) * 235.53 + 1.) * 873.726 );

    return vec2(cos(a), sin(a)) * r;
}

float Explosao( vec2 uv, float tempo )
{
    float t = fract(tempo);
    float ft = floor(tempo);

    float result = 0.;

    for (float i = 0.; i < 30.; i++)
    {
        vec2 pos = Hash12_Polar(i + ft * 0.021);
        pos *= t;

        float banana = 0.01 / length(uv - pos);
        banana *= smoothstep(0.05, 0., t) + 0.2;
        banana *= smoothstep(1., 0.4, t);
        banana *= sin(t * 30. + i) * 0.5 + 0.5;
        result += banana;
    }
    return result;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy * 2. - 1.;
    float ratio = iResolution.x / iResolution.y;
    uv.x *= ratio;

    vec3 col = vec3(0.);

    for (float i = 0.; i < 4.; i++)
    {
        float tempo = iTime + i * 0.25;
        vec2 expPos = Hash12(i + floor(tempo) * 0.21);
        expPos.x *= ratio;

        vec3 cor = sin(vec3(0.439, 0.665, 0.821) * floor(tempo + 4. * i)) * 0.25 + 0.75;

        col += Explosao(uv - expPos, tempo) * cor;
    }


    fragColor = vec4(col, 1.);
}
